import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import socket from './socket';
import { addNews, setNews } from './features/news/newsSlice';

function App() {
  const dispatch = useDispatch();
  const news = useSelector(state => state.news);
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    // Simulate initial news if none exists
    if (news.length === 0) {
      dispatch(setNews([
        { _id: '1', title: 'Welcome to News Feed', category: 'Tech' },
        { _id: '2', title: 'No real-time news yet', category: 'General' }
      ]));
    }

    // Socket connection
    socket.on('connect', () => {
      console.log('Socket connected');
      setIsConnected(true);
      socket.emit('subscribe', 'Tech');
    });

    socket.on('news', (data) => {
      console.log('Received news:', data);
      dispatch(addNews(data));
    });

    socket.on('disconnect', () => {
      console.log('Socket disconnected');
      setIsConnected(false);
    });

    return () => {
      socket.off('connect');
      socket.off('news');
      socket.off('disconnect');
    };
  }, [dispatch]);

  return (
    <div style={{ fontFamily: 'Arial', maxWidth: '800px', margin: 'auto', padding: '20px' }}>
      <h1>Real-Time News Feed</h1>
      {!isConnected && <p style={{ color: 'red' }}>Waiting for socket connection...</p>}

      {news.length === 0 ? (
        <p>No news available. Waiting for updates...</p>
      ) : (
        <ul style={{ listStyleType: 'none', padding: 0 }}>
          {news.map(n => (
            <li 
              key={n._id} 
              style={{ 
                border: '1px solid #ddd', 
                margin: '10px 0', 
                padding: '10px', 
                borderRadius: '5px' 
              }}
            >
              <strong>{n.title}</strong> - {n.category}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default App;
